      if(tile){ sfx.click(); toast("Coming soon",tile.dataset.bgSoon+" is in integration testing. Crash, Dice, Plinko and Mines are live right now as Betvora Originals.","gold"); return; }
      const dd=e.target.closest("[data-bg-dd]");
      if(dd){ sfx.click(); const drop=document.getElementById(dd.dataset.bgDd); if(drop){ const was=drop.classList.contains("open"); $$(".drop").forEach(d=>d.classList.remove("open")); if(!was) drop.classList.add("open"); } return; }
      const pub=e.target.closest("[data-bg-pub]");
      if(pub){ sfx.click(); bgPub=pub.dataset.bgPub; bgShown=BG_PAGE; $$("[data-bg-pub]").forEach(x=>x.classList.toggle("on",x===pub)); const l=$("#bgPubLabel"); if(l) l.textContent= bgPub==="all"? "All Publishers":bgPub; $$(".drop").forEach(d=>d.classList.remove("open")); bgRenderGrid(); return; }
      const so=e.target.closest("[data-bg-sort]");
      if(so){ sfx.click(); bgSort=so.dataset.bgSort; bgShown=BG_PAGE; $$("[data-bg-sort]").forEach(x=>x.classList.toggle("on",x===so)); const l=$("#bgSortLabel"); if(l) l.textContent=so.dataset.label; $$(".drop").forEach(d=>d.classList.remove("open")); bgRenderGrid(); return; }
      const tab=e.target.closest("[data-bg-tab]");
      if(tab){ sfx.click(); bgTab=tab.dataset.bgTab; $$("#bgTabs button").forEach(x=>x.classList.toggle("on",x===tab)); bgRenderBets(); return; }
      if(e.target.closest("#bgLoadBtn")){ sfx.click(); bgShown+=BG_PAGE; bgRenderGrid(); return; }
      if(e.target.closest("#bgSearchClear")||e.target.closest("#bgNoClear")){ sfx.click(); bgClearSearch(); return; }
      const mb=e.target.closest("#bgMoreBtn");
      if(mb){ const m=$("#bgMore"); if(m){ const open=m.classList.toggle("open"); mb.textContent= open? "Show less":"Show more"; } sfx.click(); return; }
