    function tileHtml(t){ return t.game? gameCardHtml(t.game) : variantCardHtml(t.v,t.parent); }
    function renderGames(cat){
      cat=cat|| ($(".pill.on")? $(".pill.on").dataset.cat : "all");
      const browsing= !!state.search || cat!=="all" || !!state.rowCat;
      const rowsEl=$("#lobbyRows"), browseEl=$("#lobbyBrowse");
      if(rowsEl) rowsEl.style.display= browsing? "none":"";
      if(browseEl) browseEl.style.display= browsing? "":"none";
      if(!browsing) return;
      const grid=$("#gamesGrid"); let shown=0;
      if(state.rowCat && !state.search){
        const rc=ROW_CATS[state.rowCat];
        grid.innerHTML= rc? rc.tiles.map(tileHtml).join("") : "";
        shown= rc? rc.tiles.length:0;
        $("#noResults").style.display= shown? "none":"block";
        $("#gamesTitle").textContent= rc? rc.title : "Betvora Originals";
        return;
      }
      grid.innerHTML=Object.keys(GAMES).map(id=>{
        const g=GAMES[id];
        const matchCat= cat==="all"||g.cat===cat;
        const matchQ= !state.search || g.name.toLowerCase().includes(state.search);
        if(!matchCat||!matchQ) return "";
        shown++;
        return gameCardHtml(id);
      }).join("");
      $("#noResults").style.display= shown? "none":"block";
      $("#gamesTitle").textContent= state.search? 'Results for "'+searchInput.value.trim()+'"' : "Betvora Originals";
    }

    /* ==================== HERO CAROUSEL ==================== */
    /* Ambient motion respects the Animations toggle: when html.no-motion is set,
       decorative JS updates are skipped so the page is fully still. */
    function motionOff(){ return document.documentElement.classList.contains("no-motion"); }
    let heroIdx=0, heroTimer=null;
    function heroGo(i){
      const slides=$$(".hero-slide"); heroIdx=(i+slides.length)%slides.length;
      slides.forEach((s,k)=>s.classList.toggle("on",k===heroIdx));
      $$(".hero-dot").forEach((d,k)=>d.classList.toggle("on",k===heroIdx));
      clearInterval(heroTimer); heroTimer=setInterval(()=>{ if(!motionOff()) heroGo(heroIdx+1); },6000);
    }
    $("#heroNext").addEventListener("click",()=>{ heroGo(heroIdx+1); sfx.click(); });
    $("#heroPrev").addEventListener("click",()=>{ heroGo(heroIdx-1); sfx.click(); });
    $$(".hero-dot").forEach(d=>d.addEventListener("click",()=>heroGo(parseInt(d.dataset.slide,10))));
    heroTimer=setInterval(()=>{ if(!motionOff()) heroGo(heroIdx+1); },6000);

