    function renderLobbyRows(){
      const host=$("#lobbyRows"); if(!host) return;
      const guest=!state.user;
      let html= guest? regBannerHtml() : "";
      LOBBY_ROWS.forEach(row=>{
        if(row==="BANNER"){ if(!guest) html+=cbBannerHtml(); return; }
        const rc=ROW_CATS[row.key], sid="strip-"+row.key;
        const tiles= rc.tiles;
        html+='<div class="lobby-row">'
          +rowHeadHtml(row.icon,row.title,row.green,'<button class="view-all" data-viewall="'+row.key+'">View all</button>',sid)
          +'<div class="row-strip" id="'+sid+'">'+tiles.map(tileHtml).join("")+'</div></div>';
      });
      if(!guest) html+=offersStripHtml();
      host.innerHTML=html;
    }
