    function lobbyOffer(key){
      if(key==="welcome"){ requireAuth(claimWelcome); return; }
      if(key==="firstdep"){ requireAuth(openWallet); return; }
      if(key==="rakeback"){ requireAuth(()=>navigate("vip")); return; }
      if(key==="race"){
        requireAuth(()=>{
          if(state.raceJoined){ toast("You're in the race","Keep wagering — your points update live."); return; }
          state.raceJoined=true; const b=$("#raceJoinBtn"); if(b) b.textContent="You're in ✓ Keep wagering"; sfx.big();
          offerSync("race","You're in ✓ Keep wagering",false);
          toast("Race joined","Every bet now earns race points. Good luck!","gold");
          renderRace();
        });
        return;
      }
      if(key==="refer"){
        requireAuth(()=>{
          const code="BETVORA-"+(state.user? acctId(state.user.email).slice(3):"GUEST");
          const link="betvora.demo/join?ref="+code;
          if(navigator.clipboard&&navigator.clipboard.writeText){ navigator.clipboard.writeText(link).then(()=>toast("Referral link copied","Share it — you earn $25 for every friend who makes a first deposit.")).catch(()=>toast("Your referral code",code)); }
          else toast("Your referral code",code);
        });
        return;
      }
      const c=LOBBY_CLAIMS[key];
      if(c){
        requireAuth(()=>{
          if(state[c.flag]){ toast("Already claimed","This offer refreshes on its own schedule — check back soon.","err"); return; }
          state[c.flag]=true; state.balance+=c.amt; renderBalance(); addTx("bonus",c.label,c.amt); sfx.coin();
          const pb=$(c.btn); if(pb){ pb.textContent="Claimed ✓"; pb.disabled=true; }
          offerSync(key,"Claimed ✓",true);
          toast(c.title,c.sub,"gold");
        });
        return;
      }
      const j=LOBBY_JOINS[key];
      if(j){
        requireAuth(()=>{
          if(state[j.flag]){ toast("You're already in",j.sub); return; }
          state[j.flag]=true; const pb=$(j.btn); if(pb) pb.textContent=j.done; sfx.big();
          offerSync(key,j.done,false);
          toast(j.title,j.sub,"gold");
        });
      }
    }
    document.addEventListener("click",e=>{
      const so=e.target.closest("[data-soon]");
      if(so){ sfx.click(); toast("Coming soon",so.dataset.soon+" is in the Betvora studio pipeline — "+so.dataset.parent+" is live and playable right now.","gold"); return; }
      const va=e.target.closest("[data-viewall]");
      if(va){ sfx.click();
        if(!state.user){ openOverlay("authOverlay"); setAuthMode("register"); toast("Members only","Log in or register to view all games and unlock the full lobby.","gold"); return; }
        state.rowCat=va.dataset.viewall; Skel.switchRender(); const t=$("#gamesTitle"); if(t) t.scrollIntoView({behavior:"smooth",block:"start"}); return; }
      if(e.target.closest("#lobbyRegBtn")){ sfx.click(); openOverlay("authOverlay"); setAuthMode("register"); return; }
      if(e.target.closest("#lobbyLoginBtn")){ sfx.click(); openOverlay("authOverlay"); setAuthMode("login"); return; }
      const sc=e.target.closest("[data-scroll]");
      if(sc){ const strip=document.getElementById(sc.dataset.strip); if(strip) strip.scrollBy({left:(parseInt(sc.dataset.scroll,10)||1)*Math.min(strip.clientWidth*0.8,640),behavior:"smooth"}); return; }
      const of=e.target.closest("[data-offer]");
      if(of && !of.disabled){ lobbyOffer(of.dataset.offer); }
    });
    /* ---- cashback banner countdown: next drop 08:00 UTC ---- */
    function cbCountdown(){
      const h=$("#cbH"), m=$("#cbM"), s=$("#cbS"); if(!h||!m||!s) return;
      const n=new Date(); const t=new Date(Date.UTC(n.getUTCFullYear(),n.getUTCMonth(),n.getUTCDate(),8,0,0));
      if(t<=n) t.setUTCDate(t.getUTCDate()+1);
      let sec=Math.max(0,Math.floor((t-n)/1000));
      const pad=x=>String(x).padStart(2,"0");
      h.textContent=pad(Math.floor(sec/3600)); m.textContent=pad(Math.floor(sec%3600/60)); s.textContent=pad(sec%60);
    }
    setInterval(cbCountdown,1000);
    renderLobbyRows(); cbCountdown();
